with zipfile.ZipFile('/home/ga/Documents/SOW-Revision 1.docx') as z:
    for name in z.namelist():
        if 'settings' in name:
            print('Settings file:', name)
            content = z.read(name).decode('utf-8', errors='ignore')
            if 'trackRevisions' in content:
                print('trackRevisions found in settings:', [line for line in content.split('><') if 'track' in line.lower()])
            else:
                print('No trackRevisions in settings!')
        if 'document' in name:
            print('Document file:', name)
            content = z.read(name).decode('utf-8', errors='ignore')
            tags = ['w:ins', 'w:del', 'w:rPrChange', 'w:pPrChange', 'w:sectPrChange', 'w:tblPrChange']
            for tag in tags:
                count = content.count(tag)
                print(f'{tag}: {count}')
"

